// Auto-generated by CAF
// T4.4: Autonomous Selector Repair Engine
// Automatically repairs broken selectors by finding alternatives

import fs from 'fs';
import path from 'path';
import * as cheerio from 'cheerio';

// ─────────────────────────────────────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────────────────────────────────────

const REPAIR_LOG_FILE = '.caf-repair-log.json';
const SNAPSHOTS_DIR = '.caf-dom-snapshots';

// Repair strategy weights
const STRATEGY_WEIGHTS = {
  dataTestId: 100,
  id: 95,
  ariaLabel: 85,
  role: 80,
  name: 75,
  placeholder: 70,
  text: 60,
  class: 40,
  tag: 20,
};

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface RepairCandidate {
  selector: string;
  score: number;
  strategy: string;
  confidence: number;   // 0-100
  similarity: number;   // 0-100, how similar to original
}

interface RepairResult {
  originalSelector: string;
  status: 'repaired' | 'multiple-options' | 'failed';
  candidates: RepairCandidate[];
  selectedRepair?: RepairCandidate;
  reason?: string;
}

interface RepairLog {
  version: string;
  updatedAt: string;
  repairs: {
    timestamp: string;
    originalSelector: string;
    newSelector: string;
    strategy: string;
    confidence: number;
    autoApplied: boolean;
  }[];
}

interface ElementContext {
  tag: string;
  id?: string;
  testId?: string;
  ariaLabel?: string;
  role?: string;
  name?: string;
  placeholder?: string;
  text?: string;
  classes: string[];
  parent?: {
    tag: string;
    id?: string;
    testId?: string;
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Repair Log Management
// ─────────────────────────────────────────────────────────────────────────────

function loadRepairLog(): RepairLog {
  if (!fs.existsSync(REPAIR_LOG_FILE)) {
    return {
      version: '1.0',
      updatedAt: new Date().toISOString(),
      repairs: [],
    };
  }

  return JSON.parse(fs.readFileSync(REPAIR_LOG_FILE, 'utf-8'));
}

function saveRepairLog(log: RepairLog): void {
  log.updatedAt = new Date().toISOString();
  fs.writeFileSync(REPAIR_LOG_FILE, JSON.stringify(log, null, 2));
}

// ─────────────────────────────────────────────────────────────────────────────
// DOM Analysis for Repair
// ─────────────────────────────────────────────────────────────────────────────

function parseSelector(selector: string): { type: string; value: string }[] {
  const parts: { type: string; value: string }[] = [];

  // Extract data-testid
  const testIdMatch = selector.match(/\[data-testid="([^"]+)"\]/);
  if (testIdMatch) {
    parts.push({ type: 'testId', value: testIdMatch[1] });
  }

  // Extract ID
  const idMatch = selector.match(/#([\w-]+)/);
  if (idMatch) {
    parts.push({ type: 'id', value: idMatch[1] });
  }

  // Extract role
  const roleMatch = selector.match(/\[role="([^"]+)"\]/);
  if (roleMatch) {
    parts.push({ type: 'role', value: roleMatch[1] });
  }

  // Extract aria-label
  const ariaMatch = selector.match(/\[aria-label="([^"]+)"\]/);
  if (ariaMatch) {
    parts.push({ type: 'ariaLabel', value: ariaMatch[1] });
  }

  // Extract tag
  const tagMatch = selector.match(/^(\w+)/);
  if (tagMatch && !['#', '[', '.'].includes(selector[0])) {
    parts.push({ type: 'tag', value: tagMatch[1] });
  }

  // Extract text
  const textMatch = selector.match(/:(?:has-text|text)\("([^"]+)"\)/);
  if (textMatch) {
    parts.push({ type: 'text', value: textMatch[1] });
  }

  return parts;
}

function findSimilarElements(
  $: cheerio.CheerioAPI,
  originalContext: { type: string; value: string }[]
): ElementContext[] {
  const candidates: ElementContext[] = [];

  $('*').each((_, el) => {
    if (el.type !== 'tag') return;

    const $el = $(el);
    const tag = el.name.toLowerCase();

    // Skip non-interactive elements
    if (['html', 'head', 'meta', 'script', 'style', 'link'].includes(tag)) {
      return;
    }

    const context: ElementContext = {
      tag,
      id: $el.attr('id'),
      testId: $el.attr('data-testid'),
      ariaLabel: $el.attr('aria-label'),
      role: $el.attr('role'),
      name: $el.attr('name'),
      placeholder: $el.attr('placeholder'),
      text: $el.text().trim().substring(0, 50),
      classes: ($el.attr('class') || '').split(/\s+/).filter(Boolean),
    };

    // Get parent context
    const $parent = $el.parent();
    if ($parent.length > 0) {
      const parentEl = $parent.get(0);
      if (parentEl && parentEl.type === 'tag') {
        context.parent = {
          tag: parentEl.name.toLowerCase(),
          id: $parent.attr('id'),
          testId: $parent.attr('data-testid'),
        };
      }
    }

    // Check if this element matches any original context hints
    let matchScore = 0;

    for (const part of originalContext) {
      switch (part.type) {
        case 'testId':
          if (context.testId?.includes(part.value.split('-')[0])) matchScore += 80;
          break;
        case 'id':
          if (context.id?.includes(part.value.split('-')[0])) matchScore += 70;
          break;
        case 'role':
          if (context.role === part.value) matchScore += 60;
          break;
        case 'tag':
          if (context.tag === part.value) matchScore += 30;
          break;
        case 'text':
          if (context.text?.toLowerCase().includes(part.value.toLowerCase())) matchScore += 50;
          break;
      }
    }

    if (matchScore > 0 || context.testId || context.id) {
      candidates.push(context);
    }
  });

  return candidates;
}

/**
 * Escape quotes in attribute values to prevent selector breakage
 */
function escapeAttrValue(value: string): string {
  return value.replace(/"/g, '\\"');
}

function generateRepairCandidates(context: ElementContext): RepairCandidate[] {
  const candidates: RepairCandidate[] = [];

  // Strategy 1: data-testid (highest priority)
  if (context.testId) {
    candidates.push({
      selector: `[data-testid="${context.testId}"]`,
      score: STRATEGY_WEIGHTS.dataTestId,
      strategy: 'data-testid',
      confidence: 95,
      similarity: 90,
    });
  }

  // Strategy 2: ID
  if (context.id) {
    candidates.push({
      selector: `#${context.id}`,
      score: STRATEGY_WEIGHTS.id,
      strategy: 'id',
      confidence: 90,
      similarity: 85,
    });
  }

  // Strategy 3: aria-label
  if (context.ariaLabel) {
    candidates.push({
      selector: `[aria-label="${escapeAttrValue(context.ariaLabel)}"]`,
      score: STRATEGY_WEIGHTS.ariaLabel,
      strategy: 'aria-label',
      confidence: 85,
      similarity: 80,
    });
  }

  // Strategy 4: role + text
  if (context.role && context.text) {
    const shortText = context.text.substring(0, 30);
    candidates.push({
      selector: `[role="${context.role}"]:has-text("${escapeAttrValue(shortText)}")`,
      score: STRATEGY_WEIGHTS.role,
      strategy: 'role+text',
      confidence: 75,
      similarity: 70,
    });
  }

  // Strategy 5: name attribute
  if (context.name) {
    candidates.push({
      selector: `${context.tag}[name="${escapeAttrValue(context.name)}"]`,
      score: STRATEGY_WEIGHTS.name,
      strategy: 'name',
      confidence: 80,
      similarity: 75,
    });
  }

  // Strategy 6: placeholder
  if (context.placeholder) {
    candidates.push({
      selector: `[placeholder="${escapeAttrValue(context.placeholder)}"]`,
      score: STRATEGY_WEIGHTS.placeholder,
      strategy: 'placeholder',
      confidence: 70,
      similarity: 65,
    });
  }

  // Strategy 7: tag + parent context
  if (context.parent?.testId) {
    candidates.push({
      selector: `[data-testid="${context.parent.testId}"] ${context.tag}`,
      score: STRATEGY_WEIGHTS.class,
      strategy: 'parent-context',
      confidence: 60,
      similarity: 55,
    });
  }

  // Sort by score descending
  return candidates.sort((a, b) => b.score - a.score);
}

// ─────────────────────────────────────────────────────────────────────────────
// Repair Engine
// ─────────────────────────────────────────────────────────────────────────────

function attemptRepair(
  brokenSelector: string,
  htmlContent: string
): RepairResult {
  const $ = cheerio.load(htmlContent);

  // Parse original selector for context hints
  const originalContext = parseSelector(brokenSelector);

  if (originalContext.length === 0) {
    return {
      originalSelector: brokenSelector,
      status: 'failed',
      candidates: [],
      reason: 'Could not parse original selector context',
    };
  }

  // Find similar elements in current DOM
  const similarElements = findSimilarElements($, originalContext);

  if (similarElements.length === 0) {
    return {
      originalSelector: brokenSelector,
      status: 'failed',
      candidates: [],
      reason: 'No similar elements found in DOM',
    };
  }

  // Generate repair candidates from each similar element
  const allCandidates: RepairCandidate[] = [];

  for (const element of similarElements) {
    const candidates = generateRepairCandidates(element);
    allCandidates.push(...candidates);
  }

  // Deduplicate by selector
  const uniqueCandidates = Array.from(
    new Map(allCandidates.map(c => [c.selector, c])).values()
  );

  // Sort by score
  uniqueCandidates.sort((a, b) => b.score - a.score);

  if (uniqueCandidates.length === 0) {
    return {
      originalSelector: brokenSelector,
      status: 'failed',
      candidates: [],
      reason: 'No viable repair candidates generated',
    };
  }

  // If top candidate has high confidence, select it
  const topCandidate = uniqueCandidates[0];

  if (topCandidate.confidence >= 85) {
    return {
      originalSelector: brokenSelector,
      status: 'repaired',
      candidates: uniqueCandidates.slice(0, 5),
      selectedRepair: topCandidate,
    };
  }

  // Multiple options, needs human review
  return {
    originalSelector: brokenSelector,
    status: 'multiple-options',
    candidates: uniqueCandidates.slice(0, 5),
    reason: 'Multiple candidates found, manual review recommended',
  };
}

function loadLatestSnapshot(pageName: string): string | null {
  if (!fs.existsSync(SNAPSHOTS_DIR)) {
    return null;
  }

  const files = fs.readdirSync(SNAPSHOTS_DIR)
    .filter(f => f.startsWith(pageName) && f.endsWith('.html'))
    .sort()
    .reverse();

  if (files.length === 0) {
    return null;
  }

  return fs.readFileSync(path.join(SNAPSHOTS_DIR, files[0]), 'utf-8');
}

// ─────────────────────────────────────────────────────────────────────────────
// CLI Entry Point
// ─────────────────────────────────────────────────────────────────────────────

function main() {
  const args = process.argv.slice(2);

  const repair = args.includes('--repair');
  const autoApply = args.includes('--auto');
  const verbose = args.includes('--verbose');

  let selector = '';
  let page = 'default';
  let snapshotPath = '';

  const selectorIdx = args.indexOf('--selector');
  if (selectorIdx !== -1 && args[selectorIdx + 1]) {
    selector = args[selectorIdx + 1];
  }

  const pageIdx = args.indexOf('--page');
  if (pageIdx !== -1 && args[pageIdx + 1]) {
    page = args[pageIdx + 1];
  }

  const snapshotIdx = args.indexOf('--snapshot');
  if (snapshotIdx !== -1 && args[snapshotIdx + 1]) {
    snapshotPath = args[snapshotIdx + 1];
  }

  console.log('═══════════════════════════════════════════════════════════════');
  console.log('  T4.4: Autonomous Selector Repair Engine');
  console.log('═══════════════════════════════════════════════════════════════');

  const repairLog = loadRepairLog();

  // Show repair history
  if (!repair) {
    console.log(`\nRepair History: ${repairLog.repairs.length} repairs`);

    if (repairLog.repairs.length > 0) {
      console.log('\nRecent Repairs:');

      for (const r of repairLog.repairs.slice(-5)) {
        const icon = r.autoApplied ? '✓' : '○';
        console.log(`  ${icon} ${r.originalSelector.substring(0, 30)}...`);
        console.log(`    → ${r.newSelector.substring(0, 30)}...`);
        console.log(`    Strategy: ${r.strategy} | Confidence: ${r.confidence}%`);
      }
    }

    console.log('\nUsage:');
    console.log('  npm run repair:selector -- --repair --selector "<selector>" --snapshot <file.html>');
    console.log('  npm run repair:selector -- --repair --selector "<selector>" --page <pageName>');
    process.exit(0);
  }

  // Repair mode
  if (!selector) {
    console.log('\n⚠ Selector required: --selector "<broken-selector>"');
    process.exit(1);
  }

  // Load HTML content
  let htmlContent: string | null = null;

  if (snapshotPath && fs.existsSync(snapshotPath)) {
    htmlContent = fs.readFileSync(snapshotPath, 'utf-8');
  } else {
    htmlContent = loadLatestSnapshot(page);
  }

  if (!htmlContent) {
    console.log('\n⚠ No DOM snapshot available.');
    console.log('  Provide: --snapshot <file.html> or capture snapshot first');
    process.exit(1);
  }

  console.log(`\nAttempting repair for: ${selector}`);

  const result = attemptRepair(selector, htmlContent);

  // Display results
  console.log(`\nStatus: ${result.status.toUpperCase()}`);

  if (result.status === 'failed') {
    console.log(`Reason: ${result.reason}`);
    process.exit(1);
  }

  if (result.candidates.length > 0) {
    console.log('\nCandidates:');
    console.log('┌──────────────────────────────────────────────────────────────┐');
    console.log('│ # │ Selector                          │ Conf │ Strategy     │');
    console.log('├──────────────────────────────────────────────────────────────┤');

    for (let i = 0; i < result.candidates.length; i++) {
      const c = result.candidates[i];
      const idx = `${i + 1}`.padStart(1);
      const selDisplay = c.selector.substring(0, 33).padEnd(33);
      const confDisplay = `${c.confidence}%`.padStart(4);
      const stratDisplay = c.strategy.padEnd(12);
      const selected = result.selectedRepair === c ? ' ←' : '  ';
      console.log(`│ ${idx} │ ${selDisplay} │ ${confDisplay} │ ${stratDisplay} │${selected}`);
    }

    console.log('└──────────────────────────────────────────────────────────────┘');
  }

  // Auto-apply or log repair
  if (result.selectedRepair) {
    console.log(`\n✓ Selected: ${result.selectedRepair.selector}`);
    console.log(`  Strategy: ${result.selectedRepair.strategy}`);
    console.log(`  Confidence: ${result.selectedRepair.confidence}%`);

    if (autoApply) {
      repairLog.repairs.push({
        timestamp: new Date().toISOString(),
        originalSelector: selector,
        newSelector: result.selectedRepair.selector,
        strategy: result.selectedRepair.strategy,
        confidence: result.selectedRepair.confidence,
        autoApplied: true,
      });

      saveRepairLog(repairLog);
      console.log('\n✓ Repair logged (auto-applied)');
    } else {
      console.log('\n⚠ Use --auto to auto-apply this repair');
    }
  } else {
    console.log('\n⚠ Manual selection required. No high-confidence repair found.');
  }

  if (verbose && result.candidates.length > 0) {
    console.log('\n───────────────────────────────────────────────────────────────');
    console.log('Full Candidate Details:');

    for (const c of result.candidates) {
      console.log(`\n${c.selector}:`);
      console.log(`  Score: ${c.score}`);
      console.log(`  Strategy: ${c.strategy}`);
      console.log(`  Confidence: ${c.confidence}%`);
      console.log(`  Similarity: ${c.similarity}%`);
    }
  }

  console.log('\n✓ SELECTOR REPAIR: COMPLETE');
}

// Guard CLI entry point
if (require.main === module) {
  main();
}

